from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject


class SessionsListSECV1(SchemaObject):
    client_ip = SchemaField(name="ClientIP", not_null=True)
    creation_time = SchemaField(name="CreationTime", not_null=True)
    expiration_time = SchemaField(name="ExpirationTime", not_null=True)
    session_id = SchemaField(name="SessionID", not_null=True)
    user = SchemaField(name="User", not_null=True)

    def __init__(self, client_ip, creation_time, expiration_time, session_id, user):
        self.client_ip = client_ip
        self.creation_time = creation_time
        self.expiration_time = expiration_time
        self.session_id = session_id
        self.user = user

        super(SessionsListSECV1, self).__init__()
